-- Add missing RLS policies for teacher_assignments table

CREATE POLICY "teacher_assignments: admin read all" ON lms.teacher_assignments
  FOR SELECT USING (
    EXISTS (SELECT 1 FROM lms.users WHERE id = auth.uid() AND role = 'admin')
